body.query:
query ToolLayout($machineIdentifier: String!) {
  resource(machineIdentifier: $machineIdentifier) {
    __typename
    ... on Tool {
      ...ToolPage
    }
  }
}

fragment ToolPage on Tool {
  id
  title
  summary
  excerpt
  body
  primaryImage {
    ...ArticleBanner
  }
  primaryLink {
    label
    url
  }
  secondaryLinks {
    label
    url
  }
  citation
  createdAt
  author
  rights
  rightsHolder
  publicationDate
}

fragment ArticleBanner on AssetImage {
  description
  title
  file {
    url
    details {
      image {
        width
        height
      }
    }
    normal: thumbor(width: 1200, height: 500)
    mobile: thumbor(width: 800, height: 400)
  }
}
